create type public.content_status as enum ('draft','scheduled','published','archived');
create type public.contact_status as enum ('new','contacted','proposal_sent','won','lost','archived');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role text not null default 'editor' check (role in ('admin','editor')), created_at timestamptz not null default now());
create table public.site_settings (id smallint primary key default 1 check (id=1), company_name text not null default 'Nelled Studio', settings jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table public.projects (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, status public.content_status not null default 'draft', category text, client_name text, year smallint, excerpt text, content jsonb not null default '{}'::jsonb, technologies text[] not null default '{}', featured boolean not null default false, sort_order int not null default 0, seo jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.blog_categories (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, description text);
create table public.blog_posts (id uuid primary key default gen_random_uuid(), slug text unique not null, title text not null, summary text, content jsonb not null default '{}'::jsonb, category_id uuid references public.blog_categories(id) on delete set null, author_id uuid references public.profiles(id) on delete set null, status public.content_status not null default 'draft', featured boolean not null default false, published_at timestamptz, seo jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.partner_categories (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null);
create table public.partners (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, category_id uuid references public.partner_categories(id) on delete set null, short_description text, content jsonb not null default '{}'::jsonb, website_url text, affiliate_url text, coupon text, featured boolean not null default false, active boolean not null default true, sort_order int not null default 0, starts_at timestamptz, ends_at timestamptz, seo jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.ad_campaigns (id uuid primary key default gen_random_uuid(), partner_id uuid references public.partners(id) on delete set null, name text not null, title text not null, description text, image_url text, cta_label text, target_url text not null, placements text[] not null, active boolean not null default true, priority int not null default 0, starts_at timestamptz, ends_at timestamptz, created_at timestamptz not null default now());
create table public.ad_events (id bigint generated always as identity primary key, campaign_id uuid not null references public.ad_campaigns(id) on delete cascade, event_type text not null check (event_type in ('impression','click')), placement text not null, page_path text not null, created_at timestamptz not null default now());
create table public.contact_requests (id uuid primary key default gen_random_uuid(), name text not null, company text, email text not null, whatsapp text, project_type text, budget_range text, message text not null, status public.contact_status not null default 'new', created_at timestamptz not null default now());
create table public.contact_notes (id uuid primary key default gen_random_uuid(), contact_id uuid not null references public.contact_requests(id) on delete cascade, author_id uuid references public.profiles(id) on delete set null, body text not null, created_at timestamptz not null default now());
create table public.media_library (id uuid primary key default gen_random_uuid(), public_id text unique not null, url text not null, alt_text text, mime_type text, bytes bigint, created_at timestamptz not null default now());

create function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.profiles where id = (select auth.uid()) and role = 'admin') $$;
revoke all on function public.is_admin() from public; grant execute on function public.is_admin() to authenticated;
alter table public.profiles enable row level security; alter table public.site_settings enable row level security; alter table public.projects enable row level security; alter table public.blog_categories enable row level security; alter table public.blog_posts enable row level security; alter table public.partner_categories enable row level security; alter table public.partners enable row level security; alter table public.ad_campaigns enable row level security; alter table public.ad_events enable row level security; alter table public.contact_requests enable row level security; alter table public.contact_notes enable row level security; alter table public.media_library enable row level security;
create policy "own profile read" on public.profiles for select to authenticated using ((select auth.uid())=id); create policy "admin profiles" on public.profiles for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy "settings public read" on public.site_settings for select to anon,authenticated using (true); create policy "settings admin write" on public.site_settings for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy "public projects" on public.projects for select to anon,authenticated using (status='published'); create policy "admin projects" on public.projects for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy "public categories" on public.blog_categories for select to anon,authenticated using (true); create policy "admin categories" on public.blog_categories for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy "public posts" on public.blog_posts for select to anon,authenticated using (status='published' and published_at <= now()); create policy "admin posts" on public.blog_posts for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy "public partner categories" on public.partner_categories for select to anon,authenticated using (true); create policy "admin partner categories" on public.partner_categories for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy "public partners" on public.partners for select to anon,authenticated using (active and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>=now())); create policy "admin partners" on public.partners for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy "public campaigns" on public.ad_campaigns for select to anon,authenticated using (active and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>=now())); create policy "admin campaigns" on public.ad_campaigns for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy "admin ad events" on public.ad_events for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy "admin contacts" on public.contact_requests for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin())); create policy "admin contact notes" on public.contact_notes for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin())); create policy "admin media" on public.media_library for all to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
grant select on public.site_settings,public.projects,public.blog_categories,public.blog_posts,public.partner_categories,public.partners,public.ad_campaigns to anon, authenticated;
grant insert,select,update,delete on public.profiles,public.site_settings,public.projects,public.blog_categories,public.blog_posts,public.partner_categories,public.partners,public.ad_campaigns,public.ad_events,public.contact_requests,public.contact_notes,public.media_library to authenticated;
